mcp:tool-listener.mcp:parameters-schema:
{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"origen": {
			"type": "string",
			"description": "Ciudad o código IATA de origen (p. ej. Madrid o MAD)"
		},
		"destino": {
			"type": "string",
			"description": "Ciudad o código IATA de destino (p. ej. Londres o LHR)"
		},
		"fecha": {
			"type": "string",
			"description": "Fecha de salida en formato AAAA-MM-DD"
		},
		"pasajeros": {
			"type": "integer",
			"minimum": 1,
			"maximum": 9,
			"description": "Número de pasajeros (1 si no lo dice)"
		}
	},
	"required": [
		"origen",
		"destino",
		"fecha"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"vueloId": {
			"type": "string",
			"description": "vueloId del vuelo elegido, copiado tal cual de buscar_vuelos (p. ej. DA1234_MADLHR_20261120)"
		},
		"pasajeros": {
			"type": "integer",
			"minimum": 1,
			"maximum": 9,
			"description": "Número de pasajeros (el mismo de la búsqueda)"
		},
		"nombre": {
			"type": "string",
			"description": "Nombre del titular"
		},
		"apellidos": {
			"type": "string",
			"description": "Apellidos del titular"
		},
		"email": {
			"type": "string",
			"description": "Email del titular"
		}
	},
	"required": [
		"vueloId",
		"nombre",
		"apellidos",
		"email"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva (6 caracteres) devuelto por reservar_vuelo"
		},
		"aeropuerto": {
			"type": "string",
			"description": "Aeropuerto AENA donde deja el coche (opcional si hay localizador)"
		},
		"fechaEntrada": {
			"type": "string",
			"description": "Entrada al parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm (opcional si hay localizador: se usa el día del vuelo)"
		},
		"fechaSalida": {
			"type": "string",
			"description": "Salida del parking (cuándo recoge el coche): AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		}
	},
	"required": [
		"fechaSalida"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva (6 caracteres) devuelto por reservar_vuelo"
		},
		"opcionId": {
			"type": "string",
			"enum": [
				"EXPRESS",
				"GENERAL",
				"LARGA_ESTANCIA"
			],
			"description": "Opción de parking elegida"
		},
		"fechaSalida": {
			"type": "string",
			"description": "Salida del parking (cuándo recoge el coche): AAAA-MM-DD o AAAA-MM-DDTHH:mm"
		},
		"fechaEntrada": {
			"type": "string",
			"description": "Entrada al parking: AAAA-MM-DD o AAAA-MM-DDTHH:mm (opcional: por defecto el día del vuelo)"
		},
		"aeropuerto": {
			"type": "string",
			"description": "Aeropuerto AENA (opcional: por defecto el de salida del vuelo)"
		},
		"matricula": {
			"type": "string",
			"description": "Matrícula del coche (opcional)"
		}
	},
	"required": [
		"localizador",
		"opcionId",
		"fechaSalida"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva (6 caracteres) devuelto por reservar_vuelo"
		}
	},
	"required": [
		"localizador"
	]
}

{
	"$schema": "http://json-schema.org/draft-07/schema#",
	"type": "object",
	"properties": {
		"localizador": {
			"type": "string",
			"description": "Localizador de la reserva (6 caracteres) devuelto por reservar_vuelo"
		}
	},
	"required": [
		"localizador"
	]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
    message: {
        messageId: uuid(),
        role: "ROLE_USER",
        metadata: {
            correlationId: vars.correlationId,
            canal: "github-copilot-mcp"
        },
        parts: [
            {
                data: {accion: vars.accion, datos: vars.datos},
                mediaType: "application/json"
            },
            {
                text: "Petición del cliente desde GitHub Copilot: " ++ vars.accion
            }
        ]
    }
}

%dw 2.0
output application/java
import * from dwl::comun::utilidades
var task = taskA2a(vars.respuestaA2a)
var textoArtifact = primero(flatten((task.artifacts default []) map (($.parts default []) filter ($.text != null) map ($.text as String))))
---
{
    estado: task.status.state default null,
    taskId: task.id default null,
    resumen: (textoArtifact default textosDe(task.status.message.parts)) default "",
    resultado: resultadoNegocio(task.artifacts default vars.respuestaA2a)
}
